use kni_core::reference_slice;
use kni_core::stroke_counter_roles as roles;
use roles::*;use reference_slice::{Point,ReferenceRing,Span,DrawnGlyph};
fn p(x:f64,y:f64)->Point{Point{x,y}}
fn ring(ps:&[(f64,f64)])->ReferenceRing{ReferenceRing{start:p(ps[0].0,ps[0].1),spans:ps[1..].iter().map(|&(x,y)|Span::Line{end:p(x,y)}).collect()}}
fn outer()->ReferenceRing{ring(&[(0.,0.),(10.,0.),(10.,10.),(0.,10.),(0.,0.)])}
fn hole()->ReferenceRing{ring(&[(2.,2.),(2.,8.),(8.,8.),(8.,2.),(2.,2.)])}
fn input(rs:Vec<ReferenceRing>)->Letterform{Letterform{scope:Scope{font:"f".into(),master:"m".into(),style:"s".into(),frame:"fu".into(),source_pin:"a".repeat(64)},glyph:DrawnGlyph{glyph_id:"arbitrary-symbol".into(),rings:rs},edges:vec![SourceEdge{edge_id:"bottom".into(),address:EdgeAddress{ring:0,span:0}}],structures:vec![],guide_relations:vec![]}}
fn explicit()->Letterform{let mut i=input(vec![outer()]);i.structures.push(Structure{id:"positive".into(),kind:StructureKind::PositiveStroke,semantic_name:"stem-boundary".into(),status:RoleStatus::Accepted,evidence:"explicit-source-structure".into(),edge_ids:vec!["bottom".into()],parent_stroke:None});i.guide_relations.push(GuideRelation{structure_id:"positive".into(),edge_id:"bottom".into(),class:"flat-baseline".into(),status:RoleStatus::Accepted,evidence:"source-class-relation".into()});i}
#[test]fn explicit_acceptance_and_binding_adapter(){let i=explicit();let r=derive_roles(&i).unwrap();assert_eq!(r.memberships[0].status,RoleStatus::Accepted);assert_eq!(r.memberships[0].class.as_deref(),Some("flat-baseline"));let es=guide_edges(&i).unwrap();assert_eq!(es[0].source_y,vec![0.,0.]);assert_eq!(es[0].class,"flat-baseline");assert_eq!(es[0].source_pin,"a".repeat(64));}
#[test]fn proposed_never_exports(){let mut i=explicit();i.structures[0].status=RoleStatus::Proposed;assert!(guide_edges(&i).unwrap().is_empty());assert_eq!(derive_roles(&i).unwrap().memberships[0].status,RoleStatus::Proposed);}
#[test]fn missing_relation_not_nearest_height(){let mut i=explicit();i.guide_relations.clear();let r=derive_roles(&i).unwrap();assert_eq!(r.memberships[0].class,None);assert!(guide_edges(&i).unwrap().is_empty());}
#[test]fn conflicting_structures_and_relations(){let mut i=explicit();let mut s=i.structures[0].clone();s.id="competing".into();i.structures.push(s);assert_eq!(derive_roles(&i).unwrap().memberships[0].status,RoleStatus::Conflicting);assert!(guide_edges(&i).unwrap().is_empty());let mut i=explicit();i.guide_relations.push(i.guide_relations[0].clone());assert_eq!(derive_roles(&i).unwrap().memberships[0].status,RoleStatus::Conflicting);}
#[test]fn unbound_edges_abstain_without_semantics(){let i=input(vec![outer(),hole()]);let r=derive_roles(&i).unwrap();assert_eq!(r.memberships[0].status,RoleStatus::Unavailable);assert_eq!(r.memberships[0].semantic_role,None);assert_eq!(r.geometry.len(),1);assert!(matches!(r.geometry[0].kind,GeometryKind::ClosedNegativeSpace{inner:1,outer:0,depth:1,opposite_winding:true}));assert_eq!(r.geometry[0].status,RoleStatus::Proposed);assert_eq!(r.geometry[0].origin,"derived from geometry");assert!(guide_edges(&i).unwrap().is_empty());}
#[test]fn same_winding_not_counter(){let h=ring(&[(2.,2.),(8.,2.),(8.,8.),(2.,8.),(2.,2.)]);let r=derive_roles(&input(vec![outer(),h])).unwrap();assert!(matches!(r.geometry[0].kind,GeometryKind::NestedSameDirection{..}));}
#[test]fn nested_depth_and_nearest_parent(){let island=ring(&[(3.,3.),(7.,3.),(7.,7.),(3.,7.),(3.,3.)]);let r=derive_roles(&input(vec![outer(),hole(),island])).unwrap();assert!(r.geometry.iter().any(|x|matches!(x.kind,GeometryKind::ClosedNegativeSpace{inner:2,outer:1,depth:2,..})));}
#[test]fn open_mouth_depth_proposed(){let u=ring(&[(0.,0.),(10.,0.),(10.,10.),(7.,10.),(7.,3.),(3.,3.),(3.,10.),(0.,10.),(0.,0.)]);let r=derive_roles(&input(vec![u])).unwrap();let pockets:Vec<_>=r.geometry.iter().filter_map(|x|if let GeometryKind::OpenBoundaryPocket{width,depth,..}=x.kind{Some((width,depth))}else{None}).collect();assert_eq!(pockets,vec![(4.,7.)]);}
#[test]fn touching_and_crossing_not_nesting(){let h=ring(&[(0.,2.),(0.,8.),(8.,8.),(8.,2.),(0.,2.)]);let r=derive_roles(&input(vec![outer(),h])).unwrap();assert!(r.geometry.is_empty());assert!(!r.unavailable.is_empty());}
#[test]fn curve_topology_unavailable_not_flattened(){let mut h=hole();h.spans[0]=Span::Cubic{control_one:p(2.,4.),control_two:p(2.,6.),end:p(2.,8.)};let r=derive_roles(&input(vec![outer(),h])).unwrap();assert!(r.geometry.is_empty());assert!(r.unavailable.iter().any(|x|x.reason.contains("curved")));}
#[test]fn malformed_identity_and_nonfinite(){let mut i=input(vec![outer()]);i.edges.push(i.edges[0].clone());assert_eq!(derive_roles(&i).unwrap_err(),Error::DuplicateEdge);let mut i=input(vec![outer()]);i.glyph.rings[0].start.x=f64::NAN;let r=derive_roles(&i).unwrap();assert!(!r.unavailable.is_empty());assert!(r.geometry.is_empty());}
#[test]fn explicit_counter_requires_accepted_positive_parent(){let mut i=explicit();i.edges.push(SourceEdge{edge_id:"other".into(),address:EdgeAddress{ring:0,span:1}});i.structures.push(Structure{id:"negative".into(),kind:StructureKind::NegativeCounter,semantic_name:"counter-boundary".into(),status:RoleStatus::Accepted,evidence:"explicit-negative-structure".into(),edge_ids:vec!["other".into()],parent_stroke:Some("positive".into())});i.structures[0].status=RoleStatus::Proposed;let r=derive_roles(&i).unwrap();assert_eq!(r.memberships.iter().find(|x|x.edge_id=="other").unwrap().status,RoleStatus::Unavailable);}
#[test]fn source_and_scope_unchanged_deterministic(){let mut i=explicit();let before=format!("{:?}",i.glyph);let a=derive_roles(&i).unwrap();i.structures.reverse();i.edges.reverse();let b=derive_roles(&i).unwrap();assert_eq!(a.memberships,b.memberships);assert_eq!(before,format!("{:?}",i.glyph));assert_eq!(a.scope,b.scope);}
#[test]fn no_class_for_curve_without_sampling_contract(){let mut i=explicit();i.glyph.rings[0].spans[0]=Span::Cubic{control_one:p(3.,0.),control_two:p(6.,0.),end:p(10.,0.)};assert!(guide_edges(&i).unwrap().is_empty());}
#[test]fn proposed_relation_not_accepted_membership(){let mut i=explicit();i.guide_relations[0].status=RoleStatus::Proposed;let r=derive_roles(&i).unwrap();assert_eq!(r.memberships[0].status,RoleStatus::Proposed);assert!(guide_edges(&i).unwrap().is_empty());}
#[test]fn self_crossing_open_zero_and_collinear_abstain(){for r in [ring(&[(0.,0.),(10.,10.),(0.,10.),(10.,0.),(0.,0.)]),ring(&[(0.,0.),(10.,0.),(10.,10.)]),ring(&[(0.,0.),(0.,0.),(10.,10.),(0.,0.)]),ring(&[(0.,0.),(5.,0.),(10.,0.),(0.,0.)])]{let r=derive_roles(&input(vec![r])).unwrap();assert!(r.geometry.is_empty());assert!(!r.unavailable.is_empty());}}
#[test]fn pockets_are_scale_translation_and_direction_covariant(){let ps=[(0.,0.),(10.,0.),(10.,10.),(7.,10.),(7.,3.),(3.,3.),(3.,10.),(0.,10.),(0.,0.)];for reverse in [false,true]{let mut transformed:Vec<_>=ps.iter().map(|(x,y)|(2.*x+11.,2.*y-7.)).collect();if reverse{transformed.reverse()}let r=derive_roles(&input(vec![ring(&transformed)])).unwrap();let pockets:Vec<_>=r.geometry.iter().filter_map(|x|if let GeometryKind::OpenBoundaryPocket{width,depth,..}=x.kind{Some((width,depth))}else{None}).collect();assert_eq!(pockets,vec![(8.,14.)]);}}
#[test]fn identities_do_not_supply_semantics(){let mut i=input(vec![outer(),hole()]);i.glyph.glyph_id="O".into();let a=derive_roles(&i).unwrap();i.glyph.glyph_id="unknown-script-mark".into();let b=derive_roles(&i).unwrap();assert_eq!(a.geometry,b.geometry);assert!(a.memberships.iter().all(|x|x.semantic_role.is_none()));}
#[test]fn invalid_counter_parent_fails_closed(){let mut i=explicit();i.structures[0].kind=StructureKind::NegativeCounter;assert_eq!(derive_roles(&i).unwrap_err(),Error::InvalidStructure);}
#[test]fn finite_overflow_unavailable_not_candidate(){let r=ring(&[(-1e308,-1e308),(1e308,-1e308),(1e308,1e308),(-1e308,1e308),(-1e308,-1e308)]);let r=derive_roles(&input(vec![r])).unwrap();assert!(r.geometry.is_empty());assert!(!r.unavailable.is_empty());}
#[test]fn malformed_relation_and_duplicate_address_rejected(){let mut i=explicit();i.guide_relations[0].edge_id="unknown".into();assert_eq!(derive_roles(&i).unwrap_err(),Error::InvalidRelation);let mut i=explicit();i.edges.push(SourceEdge{edge_id:"alias".into(),address:i.edges[0].address});assert_eq!(derive_roles(&i).unwrap_err(),Error::DuplicateAddress);}
